//github.com/powersemmi/ruststream-sqlx/blob/main/crates/ruststream-sqlx/examples/sqlx_tables_spec.rs"',children:'use chrono::{DateTime, Utc};\nuse ruststream_sqlx::dialect::Column;\nuse ruststream_sqlx::spec::{Attempt, Lease, Payload};\nuse ruststream_sqlx::{AttemptRow, InboxSpec, InboxTable, PayloadRow};\n\n/// The derive writes the description from the struct.\n#[derive(Inbox, sqlx::FromRow)]\n#[inbox(table = "email_jobs")]\nstruct Welcome {\n    #[field(id, generated)]\n    job_id: i64,\n    #[field(group)]\n    name: String,\n    #[field(attempt, generated)]\n    attempt: i16,\n    #[field(locked_until)]\n    locked_until: Option<DateTime<Utc>>,\n    #[field(payload)]\n    payload: Vec<u8>,\n}\n\n/// The same table by hand: the struct holds only what the service reads.\n#[derive(sqlx::FromRow)]\nstruct Reminder {\n    job_id: i64,\n    attempt: i16,\n    payload: Vec<u8>,\n}\n\nimpl InboxTable for Reminder {\n    type Id = i64;\n    // The settings the crate reads as types, in the order the chain sets them.\n    type Table = InboxSpec<(Lease<DateTime<Utc>>, Attempt, Payload)>;\n    const TABLE: Self::Table = InboxSpec::new("email_jobs", Column::new("job_id").generated())\n        .lease(Column::new("locked_until"))\n        .group(Column::new("name"))\n        .attempt(Column::new("attempt").generated())\n        .payload(Column::new("payload"));\n\n    fn id(&self) -> &i64 {\n        &self.job_id\n    }\n}\n\nimpl AttemptRow for Reminder {\n    type Attempt = i16;\n\n    fn attempt(&self) -> &i16 {\n        &self.attempt\n    }\n}\n\nimpl PayloadRow for Reminder {\n    type Column = Vec<u8>;\n\n    fn payload(&self) -> &[u8] {\n        &self.payload\n    }\n}\n'})})}),(0,r.jsx)(i.A,{value:"manual",label:"Manual",children:(0,r.jsx)(t.pre,{children:(0,r.jsx)(t.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream-sqlx/blob/main/crates/ruststream-sqlx/examples/manual/sqlx_tables_spec.rs"',children:'#[derive(sqlx::FromRow)]\nstruct Reminder {\n    job_id: i64,\n    attempt: i16,\n    payload: Vec<u8>,\n}\n\nimpl InboxTable for Reminder {\n    type Id = i64;\n    // The settings the crate reads as types, in the order the chain sets them.\n    type Table = InboxSpec<(Lease<DateTime<Utc>>, Attempt, Payload)>;\n    const TABLE: Self::Table = InboxSpec::new("email_jobs", Column::new("job_id").generated())\n        .lease(Column::new("locked_until"))\n        .group(Column::new("name"))\n        .attempt(Column::new("attempt").generated())\n        .payload(Column::new("payload"));\n\n    fn id(&self) -> &i64 {\n        &self.job_id\n    }\n}\n\nimpl AttemptRow for Reminder {\n    type Attempt = i16;\n\n    fn attempt(&self) -> &i16 {\n        &self.attempt\n    }\n}\n\nimpl PayloadRow for Reminder {\n    type Column = Vec<u8>;\n\n    fn payload(&self) -> &[u8] {\n        &self.payload\n    }\n}\n\nstruct Mailer;\n\nimpl Handle<Email> for Mailer {\n    fn handle(\n        &self,\n        email: &Email,\n        _outs: &(),\n        ctx: &mut Context<\'_>,\n    ) -> impl Future<Output = Result<(), HandlerOutcome>> {\n        tracing::info!(to = %email.to, group = ctx.name(), "sending");\n        ready(Ok(()))\n    }\n}\n\nfn service(pool: SqlitePool) -> RustStream {\n    let broker = SqlxBroker::new(pool)\n        .route::<Reminder>("welcomes")\n        .route::<Reminder>("reminders");\n    RustStream::new(AppInfo::new("mailer", "0.1.0")).with_broker(broker, |b| {\n        for group in ["welcomes", "reminders"] {\n            let send =\n                subscriber(group, Mailer).map_source(move |_| InboxQueue::<Reminder>::new(group));\n            b.include(send.build());\n        }\n    })\n}\n'})})})]})]})}function m(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(u,{...e})}):u(e)}},57250(e,t,n){n.d(t,{A:()=>i});var s=n(74848);n(96540);var r=n(34164),a=n(57663);function l({children:e,className:t,hidden:n}){return(0,s.jsx)("div",{role:"tabpanel